#import <UIKit/UIKit.h>
#import <objc/runtime.h>

static UIWindow *menuWindow = nil;
static UIButton *floatingBtn = nil;

// 熊猫猫图片base64
static const char *pandaImg = "";

void createFloatingButton() {
    menuWindow = [[UIWindow alloc] initWithFrame:CGRectMake(10, 200, 60, 60)];
    menuWindow.windowLevel = UIWindowLevelAlert + 1;
    menuWindow.backgroundColor = [UIColor clearColor];
    menuWindow.hidden = NO;
    
    // 解码图片
    NSData *imgData = [[NSData alloc] initWithBase64EncodedString:[NSString stringWithUTF8String:pandaImg] options:0];
    UIImage *img = [UIImage imageWithData:imgData];
    
    floatingBtn = [UIButton buttonWithType:UIButtonTypeCustom];
    floatingBtn.frame = CGRectMake(0, 0, 60, 60);
    [floatingBtn setImage:img forState:UIControlStateNormal];
    floatingBtn.layer.cornerRadius = 30;
    floatingBtn.clipsToBounds = YES;
    [floatingBtn addTarget:nil action:@selector(showMenu) forControlEvents:UIControlEventTouchUpInside];
    
    UIViewController *vc = [[UIViewController alloc] init];
    [vc.view addSubview:floatingBtn];
    menuWindow.rootViewController = vc;
}

void showMenu() {
    UIAlertController *menu = [UIAlertController alertControllerWithTitle:@"Standoff2 Flux" 
        message:"选择功能" preferredStyle:UIAlertControllerStyleActionSheet];
    
    [menu addAction:[UIAlertAction actionWithTitle:@"🔫 武器皮肤" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"🔪 刀" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"🧤 手套" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"👤 人物模型" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"🎨 ESP透视" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"⚙️ 设置" style:UIAlertActionStyleDefault handler:nil]];
    [menu addAction:[UIAlertAction actionWithTitle:@"关闭" style:UIAlertActionStyleCancel handler:nil]];
    
    [menuWindow.rootViewController presentViewController:menu animated:YES completion:nil];
}

__attribute__((constructor))
static void init() {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 3.0 * NSEC_PER_SEC), dispatch_get_main_queue(), ^{
        createFloatingButton();
    });
}
